B.ewQ=s(["record_key","more_else_record_an_idea","recorder_start_now","recorder_more_count_in","recorder_review","shell_record_button","song_more_record","ideas_on_this_phone","recorder_more_write_it_down_instead","songs_new_write_it_down","ideas_write_it_down"],t.s)
